6. Update src/app/(app)/pulse/analytics/page.tsx to render both LeadershipDashboard AND RecognitionAnalyticsSection:
  - Currently: `export default LeadershipDashboard`
  - Change to a new async server page component that renders LeadershipDashboard + RecognitionAnalyticsPage in sequence:
```typescript
import LeadershipDashboard from '@/features/pulse/analytics/components/LeadershipDashboard';
import RecognitionAnalyticsPage from '@/features/pulse/analytics/components/RecognitionAnalyticsPage';
export default async function AnalyticsPage({ searchParams }: { searchParams: Promise<{ range?: string; dept?: string; campaign?: string }> }) {
  const params = await searchParams;
  return (
    <div className='space-y-8'>
      <LeadershipDashboard />
      <RecognitionAnalyticsPage searchParams={params} />
    </div>
  );
}
```
  Note: In Next.js 16 App Router, searchParams is a Promise — must be awaited. LeadershipDashboard fetches its own session internally, so no prop drilling needed.
